//! Offline `wiremock` tests for the Milvus vector backend.
//!
//! Every test talks to a loopback mock server, so the suite needs no Milvus
//! installation, no network, and no credentials. The filter compiler, the score
//! normalization and the hit ordering are covered by pure unit tests.

use super::*;

use wiremock::matchers::{body_json, body_partial_json, header, method, path};
use wiremock::{Mock, MockServer, ResponseTemplate};

/// A schema with a primary key, one embedding, a bounded text field and a count.
fn schema() -> CollectionSchema {
    CollectionSchema::new(vec![
        FieldSchema {
            is_primary: true,
            description: Some("primary key".to_string()),
            ..FieldSchema::new("id", VectorDataType::Varchar)
        },
        FieldSchema {
            dim: Some(2),
            ..FieldSchema::new("embedding", VectorDataType::FloatVector)
        },
        FieldSchema {
            max_length: Some(64),
            ..FieldSchema::new("content", VectorDataType::Varchar)
        },
        FieldSchema::new("score", VectorDataType::Int64),
    ])
}

/// A schema whose primary key is generated by the store.
fn auto_schema() -> CollectionSchema {
    CollectionSchema {
        enable_dynamic_field: true,
        ..CollectionSchema::new(vec![
            FieldSchema {
                is_primary: true,
                auto_id: true,
                ..FieldSchema::new("id", VectorDataType::Varchar)
            },
            FieldSchema {
                dim: Some(2),
                ..FieldSchema::new("embedding", VectorDataType::FloatVector)
            },
        ])
    }
}

/// A store pointing at `server`.
fn store(server: &MockServer) -> MilvusVectorStore {
    MilvusVectorStore::new(MilvusConfig::new(server.uri())).expect("build store")
}

/// The describe payload of the [`schema`] above.
fn describe_data() -> Value {
    json!({
        "collectionName": "docs",
        "enableDynamicField": false,
        "fields": [
            {
                "fieldName": "id",
                "type": "varchar",
                "isPrimary": true,
                "autoID": false,
                "description": "primary key",
            },
            {
                "fieldName": "embedding",
                "type": "floatVector",
                "isPrimary": false,
                "params": [{"key": "dim", "value": "2"}],
            },
            {
                "fieldName": "content",
                "type": "VarChar",
                "isPrimary": false,
                "params": [{"key": "max_length", "value": "64"}],
            },
            {"fieldName": "score", "type": "INT64", "isPrimary": false},
        ],
    })
}

/// Mounts the `collections/describe` response that returns `data`.
async fn mount_describe(server: &MockServer, collection: &str, data: Value) {
    Mock::given(method("POST"))
        .and(path(COLLECTIONS_DESCRIBE))
        .and(body_json(json!({"collectionName": collection})))
        .respond_with(ResponseTemplate::new(200).set_body_json(json!({"code": 0, "data": data})))
        .mount(server)
        .await;
}

/// Mounts a successful response for `path` carrying `data`.
async fn mount_ok(server: &MockServer, endpoint: &str, data: Value) {
    Mock::given(method("POST"))
        .and(path(endpoint))
        .respond_with(ResponseTemplate::new(200).set_body_json(json!({"code": 0, "data": data})))
        .mount(server)
        .await;
}

#[tokio::test]
async fn create_collection_sends_the_schema_index_params_and_headers() {
    let server = MockServer::start().await;
    Mock::given(method("POST"))
        .and(path(COLLECTIONS_CREATE))
        .and(header("content-type", "application/json"))
        .and(header("authorization", "Bearer token-1"))
        .and(body_json(json!({
            "collectionName": "docs",
            "dbName": "db-a",
            "schema": {
                "autoID": false,
                "enableDynamicField": false,
                "fields": [
                    {
                        "fieldName": "id",
                        "dataType": "VarChar",
                        "isPrimary": true,
                        "description": "primary key",
                    },
                    {"fieldName": "embedding", "dataType": "FloatVector", "isPrimary": false, "dim": 2},
                    {"fieldName": "content", "dataType": "VarChar", "isPrimary": false, "maxLength": 64},
                    {"fieldName": "score", "dataType": "Int64", "isPrimary": false},
                ],
            },
            "indexParams": [{
                "fieldName": "embedding",
                "indexName": "embedding",
                "metricType": "COSINE",
                "params": {"index_type": "AUTOINDEX"},
            }],
            "params": {"consistencyLevel": "Bounded"},
        })))
        .respond_with(ResponseTemplate::new(200).set_body_json(json!({"code": 0, "data": {}})))
        .expect(1)
        .mount(&server)
        .await;

    let store = MilvusVectorStore::new(
        MilvusConfig::new(format!("{}/", server.uri()))
            .with_token("token-1")
            .with_db_name("db-a"),
    )
    .expect("build store");
    store
        .create_collection("docs", schema())
        .await
        .expect("create collection");
}

