#[tokio::test]
async fn describe_maps_every_supported_field_type() {
    let server = MockServer::start().await;
    mount_describe(
        &server,
        "docs",
        json!({
            "fields": [
                {"fieldName": "id", "type": "Int64", "isPrimary": true},
                {"fieldName": "embedding", "type": "FLOAT_VECTOR", "params": [{"key": "dim", "value": 3}]},
                {"fieldName": "small", "type": "int32"},
                {"fieldName": "ratio", "type": "Double"},
                {"fieldName": "weight", "type": "float"},
                {"fieldName": "flag", "type": "Boolean"},
                {"fieldName": "payload", "type": "Json"},
                {"fieldName": "tags", "type": "Array"},
            ],
        }),
    )
    .await;

    let schema = store(&server)
        .get_schema("docs")
        .await
        .expect("describe")
        .expect("existing collection");
    let types: Vec<VectorDataType> = schema.fields.iter().map(|field| field.dtype).collect();
    assert_eq!(
        types,
        vec![
            VectorDataType::Int64,
            VectorDataType::FloatVector,
            VectorDataType::Int32,
            VectorDataType::Double,
            VectorDataType::Float,
            VectorDataType::Bool,
            VectorDataType::Json,
            VectorDataType::Array,
        ]
    );
    assert_eq!(schema.fields[1].dim, Some(3));
    assert!(schema.fields[0].is_primary);
}

#[tokio::test]
async fn a_missing_collection_reports_absence() {
    let server = MockServer::start().await;
    let missing = || {
        ResponseTemplate::new(200).set_body_json(json!({
            "code": 100,
            "message": "can't find collection[database=default][collection=docs]",
        }))
    };
    for endpoint in [COLLECTIONS_DESCRIBE, COLLECTIONS_HAS, COLLECTIONS_DROP] {
        Mock::given(method("POST"))
            .and(path(endpoint))
            .respond_with(missing())
            .mount(&server)
            .await;
    }

    let store = store(&server);
    assert!(store.get_schema("docs").await.expect("describe").is_none());
    assert!(!store.collection_exists("docs").await.expect("has"));
    store.delete_collection("docs").await.expect("drop");
}

