#[test]
fn filter_compiles_logical_comparisons_and_membership() {
    let filters = json!({
        "$and": [
            {"kind": "a", "score": {"$gt": 1}},
            {
                "$or": [
                    {"kind": {"$in": ["a", "b"]}},
                    {"kind": {"$ne": "c"}},
                ],
            },
        ],
    });
    assert_eq!(
        compile_filter(&filters).expect("compile"),
        Some(
            "(kind == \"a\" and score > 1) and ((kind in [\"a\", \"b\"]) or (kind != \"c\"))"
                .to_string()
        )
    );
}

#[test]
fn filter_compiles_comparisons_and_escapes_strings() {
    assert_eq!(
        compile_filter(&json!({"score": {"$gte": 1, "$lt": 5, "$nin": ["x"]}})).expect("compile"),
        Some("score >= 1 and score < 5 and score not in [\"x\"]".to_string())
    );
    assert_eq!(
        compile_filter(&json!({"content": "a \"quoted\" \\ path"})).expect("compile"),
        Some("content == \"a \\\"quoted\\\" \\\\ path\"".to_string())
    );
    assert_eq!(
        compile_filter(&json!({"flag": true, "ratio": 0.5})).expect("compile"),
        Some("flag == true and ratio == 0.5".to_string())
    );
}

#[test]
fn filter_treats_null_and_empty_as_everything() {
    assert_eq!(compile_filter(&Value::Null).expect("null"), None);
    assert_eq!(compile_filter(&json!({})).expect("empty"), None);
    assert_eq!(
        compile_filter(&json!({"$and": []})).expect("empty and"),
        None
    );
    assert_eq!(
        compile_filter(&json!({"$or": [{"kind": "a"}]})).expect("or"),
        Some("(kind == \"a\")".to_string())
    );
}

#[test]
fn filter_rejects_constructs_milvus_cannot_express() {
    for (filters, expected) in [
        (json!({"$not": {"kind": "a"}}), "$not"),
        (json!({"a.b": 1}), "dotted field path"),
        (json!({"content": {"$contains": "x"}}), "$contains"),
        (json!({"kind": Value::Null}), "null operand"),
        (json!({"meta": {"inner": 1}}), "object literal"),
        (json!({"kind": {"$in": []}}), "empty membership list"),
        (json!({"kind": {"$in": [["a"]]}}), "array literal"),
    ] {
        let error = compile_filter(&filters).expect_err("unsupported filter");
        assert_eq!(error.kind(), ErrorKind::Unsupported, "{filters}");
        assert!(error.to_string().contains(expected), "{error}");
    }

    // A filter that is not an object names no field and is rejected as invalid.
    let error = compile_filter(&json!([{"kind": "a"}])).expect_err("non-object filter");
    assert_eq!(error.kind(), ErrorKind::Validation);
    assert!(error.to_string().contains("JSON object or null"), "{error}");
}

#[test]
fn hits_are_sorted_by_score_then_primary_key() {
    let data = json!([[
        {"id": "b", "distance": 0.0, "entity": {"id": "b"}},
        {"id": "c", "distance": 1.0, "entity": {"id": "c"}},
        {"id": "a", "distance": 0.0, "entity": {"id": "a"}},
    ]]);
    let hits = parse_hits(&data, "id", Metric::Cosine, 10).expect("hits");
    let ids: Vec<&Value> = hits.iter().map(|hit| &hit.fields["id"]).collect();
    assert_eq!(ids, vec!["c", "a", "b"]);
    assert_eq!(hits[0].score, 1.0);
    assert_eq!(hits[1].score, 0.5);

    // A flat list of hits is tolerated, and the result is truncated to `top_k`.
    let data = json!([{"id": "x", "distance": 0.0, "entity": {"id": "x"}}]);
    assert_eq!(
        parse_hits(&data, "id", Metric::Cosine, 10)
            .expect("hits")
            .len(),
        1
    );
    assert_eq!(
        parse_hits(&data, "id", Metric::Cosine, 0)
            .expect("hits")
            .len(),
        0
    );
}

#[test]
fn scores_are_normalized_per_metric() {
    let cases = [
        (Metric::Cosine, 1.0, 1.0),
        (Metric::Cosine, 0.0, 0.5),
        (Metric::Cosine, -1.0, 0.0),
        (Metric::Dot, 3.0, 1.0),
        (Metric::Dot, -3.0, 0.0),
        (Metric::Euclidean, 0.0, 1.0),
        (Metric::Euclidean, 2.0, 0.5),
        (Metric::Euclidean, 9.0, 0.0),
        (Metric::Euclidean, f64::NAN, 0.0),
        (Metric::Cosine, f64::INFINITY, 0.0),
    ];
    for (metric, distance, expected) in cases {
        let score = normalize_score(metric, distance);
        assert!(
            (score - expected).abs() < 1e-6,
            "{metric:?} {distance} -> {score}, expected {expected}"
        );
        assert!(
            (0.0..=1.0).contains(&score),
            "{metric:?} {distance} -> {score}"
        );
    }
}
